// === Tab: Drips ===
class Drip {
  constructor(x, y, size, col) {
    this.x = x;
    this.y = y;
    this.size = size;
		this.final = size/4;
    this.color = [col[0], col[1], col[2], 30];
  }
  move(){
    this.y+=1;
    if(this.size>this.final) this.size*=.98;
  }
  show(){
    noStroke();
    fill(this.color);
    ellipse(this.x, this.y, this.size, this.size);
  }
}

// === Tab: mySketch ===
let input, button1, button2, button3, button4;
let points = [];
let drips = [];
let paint = [];
let i = 0;
let word = 'processing!';
let bound;
let size, brush;
let drippage = true;
let overspray = true;
let concrete = false;
let img;

function preload() {
	font = loadFont('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/Calligraffitti_Regular.ttf');
	img = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/greywall.jpg');
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	textFont(font);
	angleMode(DEGREES);
	if (concrete) background(img);
	else background(255);
	(img);
	makeBox();
	scanWord();
}

function scanWord() {
	points = [];
	size = 3 * width / (8 + word.length);
	bound = font.textBounds(word, 0, height / 2, size);
	points = font.textToPoints(word, 0, height / 2, size, {
		sampleFactor: 2,
		simplifyThreshold: 0
	});
	paint = [random(128), random(128), random(128), 15];
	brush = size / 40;
	//drawBox(); //For debugging
}

function drawBox() {
	translate((width - bound.w) / 2 - bound.x, 0);
	noStroke();
	fill(0);
	textSize(size);
	text(word, 0, height / 2);
	noFill();
	stroke(0);
	rect(bound.x, bound.y, bound.w, bound.h);
}

function draw() {
	for (let step = 0; step < 10; step += 1) {
		push();
		fill(paint[0], paint[1], paint[2], paint[3]);
		noStroke();
		translate((width - bound.w) / 2 - bound.x, 0);
		translate(points[i].x, points[i].y);
		rotate(points[i].alpha);
		rectMode(CENTER);
		if (overspray && i < points.length - 10) {
			for (let i = 0; i < int(size / 10); i++) {
				let pos = p5.Vector.random2D();
				let rad = 1 + random(3 * brush, 10 * brush);
				pos.mult(rad);
				let s = (width / 20) / rad;
				ellipse(pos.x, pos.y, s, s);
			}
		}
		rect(0, 0, 2 * brush, 4 * brush, brush, brush, brush, brush);
		fill(0, 20);
		ellipse(0, 2 * brush, 2*brush, 2*brush);
		ellipse(0, -2 * brush, 2*brush, 2*brush);
		if (i < points.length - 1) {
			i += 1;
		}
		if (points[i].x - points[i - 1].x > 15) paint = [random(128), random(128), random(128), 15];
		pop();
	}
	if (drippage && frameCount % 50 == 0 && i < points.length - 10) {
		drips.push(new Drip((width - bound.w) / 2 - bound.x + points[i].x, points[i].y, random(3 * brush, 4 * brush), paint));
	}
	for (let i = 0; i < drips.length; i++) {
		drips[i].move();
		drips[i].show();
		if (drips[i].y > height) {
			drips.splice(i, 1);
		}
	}
}

function newWord() {
	if (input.value()) {
		if (concrete) background(img);
		else background(255);
		drips = [];
		word = input.value().toLowerCase();
		scanWord();
		i = 0;
	}
}

function makeBox() {
	input = createInput();
	input.position(width / 2 - 90, 20);
	button1 = createButton('new word');
	button1.position(width / 2 + 90, 20);
	button1.mousePressed(newWord);
	button2 = createButton('drips off');
	button2.position(width / 2 + 170, 20);
	button2.mousePressed(toggleDrippage);
	button3 = createButton('overspray off');
	button3.position(width / 2 + 240, 20);
	button3.mousePressed(toggleOverspray);
	button4 = createButton('concrete on');
	button4.position(width / 2 + 340, 20);
	button4.mousePressed(toggleConcrete);
}

function toggleDrippage() {
	drippage = !drippage;
	if (drippage) button2.html('drips off');
	else button2.html('drips on');
}

function toggleOverspray() {
	overspray = !overspray;
	if (overspray) button3.html('overspray off');
	else button3.html('overspray on');
}

function toggleConcrete() {
	concrete = !concrete;
	if (concrete) button4.html('concrete off');
	else button4.html('concrete on');
}

function keyPressed() {
	if (keyCode == 13) newWord();
}

